class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const mkTable = () => ({ t: 'table', m: new Map(), hdr: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function parseLine(line, root, st) {
  let p = 0
  const skip = () => { while (p < line.length && isWs(line[p])) p++ }
  const atEnd = () => p >= line.length || line[p] === '#' || line[p] === ';'

  function quoted(q) {
    // line[p] === q
    p++
    let out = ''
    for (;;) {
      if (p >= line.length) fail('unterminated string')
      const c = line[p]
      if (c === q) { p++; return out }
      if (q === '"' && c === '\\') {
        p++
        if (p >= line.length) fail('unterminated string')
        const e = line[p]
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = line.slice(p + 1, p + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          p += 4
        } else fail('invalid escape \\' + String.fromCodePoint(line.codePointAt(p)))
        p++
        continue
      }
      out += c
      p++
    }
  }

  function name() {
    const c = line[p]
    if (c === '"' || c === "'") return quoted(c)
    if (!isBare(c)) fail('expected a name')
    const s = p
    while (isBare(line[p])) p++
    return line.slice(s, p)
  }

  function dotted() {
    const parts = [name()]
    for (;;) {
      const save = p
      skip()
      if (line[p] === '.') {
        p++
        skip()
        parts.push(name())
      } else { p = save; break }
    }
    return parts
  }

  function value(inInline) {
    skip()
    const c = line[p]
    if (p >= line.length || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: quoted('"') }
    if (c === "'") return { t: 'string', v: quoted("'") }
    if (c === '[') {
      p++
      const items = []
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated array')
        if (line[p] === ']') { p++; return { t: 'array', items } }
        items.push(value())
        skip()
        if (atEnd()) fail('unterminated array')
        if (line[p] === ',') { p++; continue }
        if (line[p] === ']') { p++; return { t: 'array', items } }
        fail('unterminated array')
      }
    }
    if (c === '{') {
      p++
      const tbl = mkTable()
      skip()
      if (atEnd()) fail('unterminated inline table')
      if (line[p] === '}') { p++; return tbl }
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated inline table')
        const keys = dotted()
        skip()
        if (line[p] !== '=') fail('expected = in an inline table')
        p++
        const v = value()
        assign(tbl, st.pathOf ? [] : [], keys, v, st.inlinePrefix)
        skip()
        if (atEnd()) fail('unterminated inline table')
        if (line[p] === ',') { p++; continue }
        if (line[p] === '}') { p++; return tbl }
        fail('unterminated inline table')
      }
    }
    const s = p
    while (p < line.length && !isWs(line[p]) && line[p] !== ',' && line[p] !== ']' && line[p] !== '}') p++
    const w = line.slice(s, p)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const D = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
