  function assign(tbl, _unused, keys, v, base) {
    base = base || st.cur
    let cur = tbl
    const path = base.slice()
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i]
      path.push(k)
      const ex = cur.m.get(k)
      if (!ex) { const n = mkTable(); cur.m.set(k, n); cur = n }
      else if (ex.t === 'table') cur = ex
      else if (ex.t === 'aot') cur = ex.items[ex.items.length - 1]
      else fail(path.join('.') + ' is not a table')
    }
    const k = keys[keys.length - 1]
    path.push(k)
    if (cur.m.has(k)) fail('key ' + path.join('.') + ' is defined twice')
    cur.m.set(k, v)
  }

