    if (arr) p++
    skip()
    const keys = dotted()
    skip()
    if (line[p] !== ']') fail('unterminated table header')
    p++
    if (arr) {
      if (line[p] !== ']') fail('unterminated table header')
      p++
    }
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    let cur = root
    const path = []
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i]
      path.push(k)
      const ex = cur.m.get(k)
      if (!ex) { const n = mkTable(); cur.m.set(k, n); cur = n }
      else if (ex.t === 'table') cur = ex
      else if (ex.t === 'aot') cur = ex.items[ex.items.length - 1]
      else fail(path.join('.') + ' is not a table')
    }
    const k = keys[keys.length - 1]
    path.push(k)
    const ex = cur.m.get(k)
    if (arr) {
      const n = mkTable()
      if (!ex) cur.m.set(k, { t: 'aot', items: [n] })
      else if (ex.t === 'aot') ex.items.push(n)
      else fail(path.join('.') + ' is not an array of tables')
      st.table = n
    } else {
      if (!ex) { const n = mkTable(); n.hdr = true; cur.m.set(k, n); st.table = n }
      else if (ex.t === 'table') {
        if (ex.hdr) fail('table ' + path.join('.') + ' is defined twice')
        ex.hdr = true
        st.table = ex
      } else fail(path.join('.') + ' is not a table')
    }
    st.cur = path
    return
  }

