  skip()
  if (line[p] !== '=') fail('expected key = value')
  p++
  st.inlinePrefix = st.cur.concat(keys)
  const v = value()
  skip()
  if (!atEnd()) fail('trailing text after a value')
  assign(st.table, null, keys, v, st.cur)
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n.m)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'aot': case 'array': {
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    }
    default: return JSON.stringify(n.v)
  }
}

function toKeys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const c = n.m.get(k)
      const p = path ? path + '.' + k : k
      out.push(p + ' ' + (c.t === 'aot' ? 'array' : c.t))
      toKeys(c, p, out)
    }
  } else if (n.t === 'aot' || n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + (c.t === 'aot' ? 'array' : c.t))
      toKeys(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const root = mkTable()
const st = { table: root, cur: [] }
