  lines.forEach((l, i) => {
    try { parseLine(l, root, st) } catch (e) {
      if (e instanceof Fail) e.message = `line ${i + 1}: ${e.message}`
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  toKeys(root, '', out)
  process.stdout.write(out.map((x) => x + '\n').join(''))
}
"}

